export type ID = string;

export type User = {
  id: ID;
  name: string;
  email: string;
};

export type Project = {
  id: ID;
  name: string;
  description: string;
  memberIds: ID[];
};

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export type Task = {
  id: ID;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: ID | null;
  projectId: ID;
};

export type Comment = {
  id: ID;
  taskId: ID;
  authorId: ID;
  body: string;
  createdAt: string; // ISO
};

export type Notification = {
  id: ID;
  userId: ID;
  message: string;
  read: boolean;
  createdAt: string;
};

type Callback = (payload: any) => void;

class EventBus {
  private subs: Map<string, Callback[]> = new Map();

  publish(event: string, payload: any): void {
    const cbs = this.subs.get(event) || [];
    for (const cb of cbs) {
      // deliver asynchronously to avoid accidental sync coupling
      setImmediate(() => cb(payload));
    }
  }

  subscribe(event: string, callback: Callback): void {
    const arr = this.subs.get(event) || [];
    arr.push(callback);
    this.subs.set(event, arr);
  }
}

export const eventBus = new EventBus();

import { v4 as uuidv4 } from 'crypto';
import { User, ID } from '../types';

// Note: Node's crypto doesn't export v4 directly in older versions, so implement simple uuid
function uuid(): ID {
  return ([1e7] as any+-1e3+-4e3+-8e3+-1e11).toString();
}

export class UserService {
  private store: Map<ID, User> = new Map();

  list(): User[] {
    return Array.from(this.store.values());
  }

  create(input: { name: string; email: string }): User {
    const id = Math.random().toString(36).slice(2, 9);
    const user: User = { id, ...input };
    this.store.set(id, user);
    return user;
  }

  get(id: ID): User | null {
    return this.store.get(id) ?? null;
  }

  update(id: ID, input: { name?: string; email?: string }): User | null {
    const u = this.store.get(id);
    if (!u) return null;
    const updated = { ...u, ...input };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: ID): boolean {
    return this.store.delete(id);
  }
}

